/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: PublicationControl, Item
 *   Functions: uploadedFile, publicationControl, coverRecoveryDiagnostics, distinctDecisions, setup,
 *              expectStandaloneAdministration, createRoutes, releaseId, releaseKey, lookupCandidate,
 *              lookupGroup, lookupView, appliedRelease, uploadedProject, summaryProject, summaryRegion,
 *              publishFromSummary, expectLunaAfterLookup, noOverflow
 * Tests
 *   - admin explicitly opens workbench, adopts only selected suggestion, and User view hides private project
 *   - cancelled cover cleanup remains reachable when the owner disappears, without restoring private metadata
 *   - reopening a visited catalog owner after a confirmed deletion drops its old buffer and cancels with a null revision
 *   - an unconfirmed publication can be cancelled and reviewed while exact cleanup keeps a new approval locked
 *   - ordinary account has no admin switch and requests no admin data
 *   - mobile administrator control and workbench remain accessible without horizontal overflow
 *   - private upload retries the same multipart operation and publication waits for confirmed completion
 *   - existing catalog edits and Page placement visibility require separate explicit approvals
 *   - administrator placement layout reflows at 390px and a 200 percent equivalent viewport
 *   - one approval uploads files sequentially and leaving Admin view stops after the current file
 *   - files chosen without a folder need no folder name
 *   - a new import starts public, and the create request carries no draft
 *   - Artist entries reorder by keyboard with an announced move and kept focus, save as one value, and reflow at 320, 768 and 1440 px
 *   - several Artist entries and a label are decided one row each and published in one approval that lists them, linking every confirmed identity
 *   - values written from file tags are marked in the editor, and the confirmation marks entries and the label that rest only on file tags
 *   - an unsaved title edit is published in one approval without Save, and the editor then shows it saved
 *   - an import with no candidates publishes without answering identity questions
 *   - a folder import uploads, prefills from file tags, applies the one matching release lookup found and publishes after one confirmation
 *   - a tie shows only the values that differ with each release's barcode, catalogue number, country and medium, and choosing one lets Publish open
 *   - a lookup value that differs from the administrator's own is answered from the keyboard, and the summary reflows at 320, 768 and 1440 px
 *   - an unavailable lookup offers a free retry first and the paid Luna AI button after the lookup controls, a retry that stays unavailable keeps both, and Luna AI runs only after its confirmation shows the budget
 *   - without a folder or usable tags the summary offers an empty name box, which looks up a typed name from the keyboard, and the paid Luna AI button after it
 *   - the name box's optional Artist: an Artist alone cannot look up, a link in it is refused in place, and a typed Artist is sent with the name and shown again with its run
 *   - after a lookup finds no release the paid Luna AI button is offered after the name box, and its ticked entries, label and Disc Number are preselected and approved in one confirmation
 *   - an image every file shares is chosen automatically until the administrator chooses, and the summary and confirmation show the choice
 *   - a release with front artwork shows a protected preview, Publish waits while its cover is staged, and the staged lookup cover is then chosen automatically and published
 *   - an iTunes-only result applied after MusicBrainz stayed unavailable is marked iTunes only and not checked against MusicBrainz, its values stay flagged, and it publishes after one confirmation
 *   - an append to an Album with an expected tracklist shows each file's row and flags, numbers the files in one field save, lists the rows in the confirmation, and reflows at 320 px
 * @end-catalog */

import { expect, test, type Page, type Request } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import { createHash } from 'node:crypto';
import { mkdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { applyDraftChanges, artistEntry, capabilities, detail, entryKey, labelEntry, lookupResponse, projectId, session, slotId, slotTwo, viewer } from '../src/features/admin/adminFixtures.testSupport';

/** The file part of one queued multipart upload, so mocked assets carry the real length and SHA-256. */
function uploadedFile(request: Request) {
  const raw = request.postDataBuffer()!, start = raw.indexOf('\r\n\r\n') + 4, bytes = raw.subarray(start, raw.lastIndexOf('\r\n--'));
  return { byteLength: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex') };
}

/** Admission and completion are independent server events, not counts of automatic status reads. */
interface PublicationControl { admission: Promise<void>; completion: Promise<void> }
function publicationControl() {
  let admit!: () => void, complete!: () => void;
  const admission = new Promise<void>(resolve => { admit = resolve; });
  const completion = new Promise<void>(resolve => { complete = resolve; });
  return { admission, completion, admit, complete };
}

/** Preserve native input and navigation evidence without querying a possibly stalled page after failure. */
async function coverRecoveryDiagnostics(page: Page) {
  const events: unknown[] = [], prefix = '[cover-recovery-input]';
  const record = (event: unknown) => { events.push(event); if (events.length > 60) events.shift(); };
  const consoleEvent = (message: import('@playwright/test').ConsoleMessage) => {
    if (!message.text().startsWith(prefix)) return;
    try { record(JSON.parse(message.text().slice(prefix.length))); } catch { /* Ignore unrelated console text. */ }
  };
  const navigated = (frame: import('@playwright/test').Frame) => { if (frame === page.mainFrame()) record({ type: 'navigation', path: new URL(frame.url()).pathname }); };
  const requested = (request: import('@playwright/test').Request) => {
    const path = new URL(request.url()).pathname;
    if (/^\/api\/admin\/v1\/catalog\/(artist|album)(\/|$)/.test(path)) record({ type: 'request', method: request.method(), path });
  };
  const crashed = () => record({ type: 'crash' }), closed = () => record({ type: 'close' });
  page.on('console', consoleEvent); page.on('framenavigated', navigated); page.on('request', requested); page.on('crash', crashed); page.on('close', closed);
  await page.addInitScript(({ prefix }) => {
    const describe = (target: EventTarget | null) => {
      if (!(target instanceof Element)) return null;
      const details = target.closest('details');
      if (details?.querySelector('summary')?.textContent !== 'Recover cover operations for an item') return null;
      return { tag: target.tagName, valueLength: target instanceof HTMLInputElement ? target.value.length : undefined,
        disabled: target instanceof HTMLButtonElement ? target.disabled : undefined, open: details.open };
    };
    for (const type of ['pointermove', 'pointerdown', 'pointerup', 'mousedown', 'mouseup', 'click', 'focusin', 'focusout', 'submit']) {
      document.addEventListener(type, event => {
        const target = describe(event.target);
        if (target) console.debug(prefix + JSON.stringify({ type, trusted: event.isTrusted, target,
          active: describe(document.activeElement), path: location.pathname, time: performance.now() }));
      }, true);
    }
  }, { prefix });
  return {
    snapshot: () => ({ path: new URL(page.url()).pathname, closed: page.isClosed(), events }),
    dispose: () => { page.off('console', consoleEvent); page.off('framenavigated', navigated); page.off('request', requested); page.off('crash', crashed); page.off('close', closed); }
  };
}

/** A distinct identity for every Artist entry, the Album and each track, as an approval of a reviewed project carries them. */
function distinctDecisions(item: ReturnType<typeof detail>) {
  const fresh = { action: 'create-distinct', candidateId: null, candidateRevision: null } as const;
  return [...item.draft.album.artists.map(entry => ({ scope: 'artist' as const, slotId: null, entryKey: entry.key, boundName: entry.name, ...fresh })), { scope: 'album' as const, slotId: null, entryKey: null, boundName: null, ...fresh },
    ...item.draft.tracks.map(track => ({ scope: 'track' as const, slotId: track.slotId, entryKey: null, boundName: null, ...fresh }))];
}

async function setup(page: Page, admin = true, media = false, publication?: PublicationControl) {
  let item = detail(); const writes: Array<{ path: string; body: Record<string, unknown> }> = [];
  let uploadAttempts = 0; let publicationReads = 0;
  let publicationComplete = false;
  void publication?.completion.then(() => { publicationComplete = true; });
  if (media) {
    item.capabilities = { analysis: true, upload: true, publish: true }; item.upload.available = true; item.publication = 'notStarted'; item.draft.album.title = 'Reviewed Album'; item.draft.album.artists = [artistEntry('Synthetic artist')]; item.draft.tracks.forEach((track, index) => { track.title = `Song ${index + 1}`; track.trackNumber = index + 1; });
    // A folderless project, so its files are reselected individually by name and size.
    item.manifest = { rootLabel: '', files: item.manifest.files.map(file => ({ ...file, relativePath: file.filename })) };
    // Reviewed: a distinct identity for the entry, the Album and both tracks, so the confirmation can be approved.
    item.decisions = distinctDecisions(item);
  }
  const headers = { 'X-Finitude-Account-Viewer': viewer, 'Cache-Control': 'no-store' };
  await page.route('**/auth/browser/session', route => route.fulfill({ json: { user: { ...session.user, role: admin ? 'admin' : 'user' } } }));
  await page.route('**/api/listener/v1/capabilities', route => route.fulfill({ json: { playlists: false } }));
  await page.route('**/api/listener/v1/personalization-capabilities', route => route.fulfill({ json: { contractVersion: 1, deterministicDiscovery: false, artistFollows: false } }));
  await page.route('**/api/listener/v1/home', route => route.fulfill({ json: { title: 'Synthetic Home', sections: [] }, headers }));
  await page.route('**/content/me/playlists?limit=50', route => route.fulfill({ json: { items: [], nextCursor: null }, headers }));
  await page.route('**/api/admin/v1/**', async route => {
    expect(route.request().headers()['x-finitude-account-viewer']).toBe(viewer);
    const path = new URL(route.request().url()).pathname;
    if (path.endsWith('capabilities')) return route.fulfill({ json: { ...capabilities, catalog: { editing: true, visibility: true } }, headers });
    // Review and every publication confirmation read the duplicate candidates; this project has none.
    if (path.endsWith('/duplicate-candidates')) return route.fulfill({ json: { items: [], memberMatchesComplete: true }, headers });
    // The Review and publish summary reads the lookup view and summary state; no lookup has run for this project, and its
    // pending suggestions are listed as the server lists them.
    if (path.endsWith('/lookup') && route.request().method() === 'GET') return route.fulfill({ json: lookupResponse({}, item), headers });
    if (route.request().method() === 'POST' && path.endsWith('/reconcile')) {
      // HEAD-only reconciliation finds nothing yet, so the unknown upload stays unknown.
      const body = route.request().postDataJSON(); writes.push({ path, body });
      return route.fulfill({ json: { item, receipt: null }, headers });
    }
    if (route.request().method() === 'POST' && path.includes('/assets/')) {
      const request = route.request(), slot = decodeURIComponent(path.split('/').at(-1)!); uploadAttempts++; const operationId = request.headers()['idempotency-key'], revision = request.headers()['if-match'];
      writes.push({ path, body: { operationId, revision, bytes: request.postDataBuffer()?.toString('base64') } });
      item.assets = [...item.assets.filter(asset => asset.slotId !== slot), { slotId: slot, state: uploadAttempts === 1 ? 'unknown' : 'ready', ...uploadedFile(request), contentType: 'audio/mpeg', tags: null, recovery: { operationId, expectedRevision: Number(revision), kind: 'upload', startedByMe: true } }]; item.revision++;
      return route.fulfill({ json: { item, receipt: { operationId, kind: 'upload', revision: item.revision } }, headers });
    }
    if (route.request().method() === 'POST') {
      const body = route.request().postDataJSON(); writes.push({ path, body });
      if (path.endsWith('/publish')) {
        // One-step approval: the shown changes, decisions, preselections and cover, bound to the saved project by revision and digest.
        expect(body).toEqual({ operationId: expect.any(String), expectedRevision: item.revision, changes: expect.any(Array), decisions: item.decisions, selectedCoverSlotId: item.selectedCoverSlotId, approvalDigest: item.approvalDigest, preselections: expect.any(Array), musicBrainzIds: expect.any(Array),
          suggestionTicks: { generation: item.analysis.generation, ticked: [], unticked: item.suggestions.filter(suggestion => suggestion.decision === 'pending').map(suggestion => suggestion.id) } });
        item.draft = applyDraftChanges(item.draft, body.changes); item.publication = 'preparing'; item.revision++;
        if (publication) await publication.admission;
        return route.fulfill({ status: 202, json: { item, receipt: { operationId: body.operationId, kind: 'publish', revision: item.revision } }, headers });
      }
      if (path.endsWith('/adopt')) {
        expect(body.selectedIds).toEqual([item.suggestions[0].id]);
        item.draft.album.title = String(item.suggestions[0].value); item.suggestions[0].decision = 'accepted'; item.revision++;
        return route.fulfill({ json: { item, receipt: { operationId: body.operationId, kind: 'adopt', revision: item.revision } }, headers });
      }
      return route.fulfill({ json: { item, receipt: { operationId: body.operationId, kind: 'create', revision: item.revision } }, status: 201, headers });
    }
    if (path === '/api/admin/v1/imports') {
      const { manifest, draft, suggestions, decisions: _decisions, capabilities: _capabilities, receipts: _receipts, assets: _assets, published: _published, publicationRecovery: _recovery, selectedCoverSlotId: _selectedCover, coverChoice: _coverChoice, approvalDigest: _approvalDigest, valueRevision: _valueRevision, automaticPaths: _automaticPaths, lookupPaths: _lookupPaths, possibleLabelEntryKeys: _possibleLabels, ...common } = item;
      return route.fulfill({ json: { items: [{ ...common, title: draft.album.title, rootLabel: manifest.rootLabel, artistName: draft.album.artists[0]?.name ?? '', visibility: draft.album.visibility, pendingSuggestions: suggestions.filter(s => s.decision === 'pending').length }], counts: { all: 1, analyzing: 0, awaitingReview: 1, needsAttention: 0, completed: 0 }, nextCursor: null }, headers });
    }
    if (item.publication === 'preparing' && (publication ? publicationComplete : ++publicationReads > 1)) { item.publication = 'complete'; item.published = { albumId: '111111111111111111111111', artistIds: ['222222222222222222222222'], organizationId: null, trackIds: ['333333333333333333333333'] }; item.revision++; }
    return route.fulfill({ json: { item, receipt: null }, headers });
  });
  return writes;
}

/** Admission gates and private management both use one main without accessible listener controls. */
async function expectStandaloneAdministration(page: Page, currentView?: string) {
  await expect(page.locator('main')).toHaveCount(1);
  await expect(page.getByRole('main')).toHaveCount(1);
  await expect(page.getByRole('main')).toBeVisible();
  for (const [role, name] of [
    ['navigation', 'Primary'], ['search', 'Global search'],
    ['searchbox', 'Search artists, organizations, albums, and MediaTracks'],
    ['complementary', 'Finitude Library'], ['complementary', 'Now Playing details'],
    ['region', 'Now playing'], ['group', 'Playback controls']
  ] as const) await expect(page.getByRole(role, { name, exact: true })).toHaveCount(0);
  await expect(page.locator('#library-sidebar')).toBeHidden();
  await expect(page.locator('#now-playing-aside')).toBeHidden();
  await expect(page.getByRole('region', { name: 'Now playing', exact: true, includeHidden: true })).toBeHidden();
  if (currentView) await expect(page.getByRole('button', { name: currentView, exact: true })).toBeVisible();
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth && document.body.scrollWidth <= innerWidth)).toBe(true);
}
test.afterEach(async ({ page }, result) => {
  if (result.status === 'passed' && new URL(page.url()).pathname.startsWith('/finitude/admin')) await expectStandaloneAdministration(page);
});

