// Metadata lookup and the Review and publish summary. The lookup view and summary state are shaped as the server's
// allowlist returns them (src/administration/lookup/lookupView.ts, src/administration/import/adminImportSummary.ts).
type Item = ReturnType<typeof detail>;
const releaseId = (n: number) => `0000000b-0000-4000-8000-00000000000${n}`;
const releaseKey = (n: number) => `musicbrainz:${releaseId(n)}`;
const lookupCandidate = (n: number) => ({ key: releaseKey(n), releaseId: releaseId(n), status: 'matching', title: n === 1 ? 'Synthetic Album' : 'Synthetic Album (Deluxe)', artist: 'Synthetic Lead',
  label: `Label ${n}`, catalogNumber: `SYN-00${n}`, barcode: '4006381333931', country: n === 1 ? 'JP' : 'US', date: { year: 2021, month: 5, day: 1 }, formats: [n === 1 ? 'CD' : 'Digital Media'], trackCount: 2,
  comparison: { trackCount: { local: 2, candidate: 2 }, discCount: { local: null, candidate: 1 }, differences: [], unknownLocalDurations: 0, unknownCandidateDurations: 0 }, groupKey: String(n).repeat(64), artistMismatch: false });
const lookupGroup = (n: number) => ({ groupKey: String(n).repeat(64), representativeKey: releaseKey(n), memberKeys: [releaseKey(n)], proposal: { albumTitle: lookupCandidate(n).title,
  artists: [{ name: 'Synthetic Lead', role: 'primary', joinPhrase: null }], label: `Label ${n}`, releaseDate: { year: 2020, month: null, day: null },
  tracks: [{ discNumber: 1, trackNumber: 1, title: 'First' }, { discNumber: 1, trackNumber: 2, title: 'Second' }] } });
const lookupView = (extra: Record<string, unknown> = {}) => ({ run: 1, state: 'complete', issue: null, outcome: 'candidates', input: { trigger: 'tags', submitted: null }, candidates: [], groups: [],
  preselection: null, disclosure: null, applied: null, staleFiles: [], needsAnswer: { tie: false, conflicts: [] }, blocking: false, ...extra });
const appliedRelease = (n: number, choice: 'preselected' | 'chosen', extra: Record<string, unknown> = {}) => ({ run: 1, candidateKey: releaseKey(n), releaseId: releaseId(n), choice,
  basis: choice === 'chosen' ? 'chosen' : 'onlyMatchingGroup', values: [{ path: 'album.title', slotId: null }], conflicts: [], flagged: [], ...extra });
/** An uploaded, prefilled project: both files confirmed, values from file tags, and a reviewed identity for each row. */
function uploadedProject(): Item {
  const item = detail(), [first, second] = item.draft.tracks;
  item.capabilities = { analysis: true, upload: true, publish: true }; item.upload = { ready: 2, total: 2, available: true }; item.publication = 'notStarted'; item.suggestions = [];
  Object.assign(item.draft.album, { title: 'Synthetic Album', artists: [artistEntry('Synthetic Lead')] });
  Object.assign(first, { title: 'First', discNumber: 1, trackNumber: 1 }); Object.assign(second, { title: 'Second', discNumber: 1, trackNumber: 2 });
  item.assets = [first, second].map(track => ({ slotId: track.slotId, state: 'ready' as const, byteLength: 100, sha256: 'a'.repeat(64), contentType: 'audio/mpeg', tags: null, recovery: null }));
  item.decisions = distinctDecisions(item);
  return item;
}
/**
 * Serves one import project and its summary read (GET …/lookup answers `state.lookup` and `state.summary` over the defaults);
 * `write` applies each write and returns its receipt kind, and every write is recorded. The duplicate candidates read lists
 * `candidates` (none by default). Registered after setup, so it serves every request for this project.
 */
async function summaryProject(page: Page, initial: Item, write: (state: { item: Item; lookup: Record<string, unknown> | null; summary: Record<string, unknown> }, action: string, body: any) => string,
  candidates: unknown[] = []) {
  const headers = { 'X-Finitude-Account-Viewer': viewer, 'Cache-Control': 'no-store' };
  const state = { item: initial, lookup: null as Record<string, unknown> | null, summary: {} as Record<string, unknown>, writes: [] as { action: string; body: any }[] };
  await page.route(`**/api/admin/v1/imports/${projectId}**`, async route => {
    const request = route.request(), action = new URL(request.url()).pathname.split('/').slice(6).join('/');
    if (action === 'duplicate-candidates') return route.fulfill({ json: { items: candidates, memberMatchesComplete: true }, headers });
    if (request.method() === 'GET') return route.fulfill({ json: action === 'lookup' ? { lookup: state.lookup, revision: state.item.revision, valueRevision: state.item.valueRevision,
      summary: { ...lookupResponse().summary, ...state.summary } } : { item: state.item, receipt: null }, headers });
    const body = request.postDataJSON(); state.writes.push({ action, body });
    const kind = write(state, action, body), revision = state.item.revision + 1;
    state.item = { ...state.item, revision, receipts: [...state.item.receipts, { operationId: body.operationId, kind: kind as never, revision }] };
    return route.fulfill({ json: { item: state.item, receipt: { operationId: body.operationId, kind, revision } }, headers });
  });
  return state;
}
const summaryRegion = (page: Page) => page.getByRole('region', { name: 'Review and publish', exact: true });
const publishFromSummary = (page: Page) => summaryRegion(page).getByRole('button', { name: 'Review and approve publishing', exact: true });
/**
 * The summary's paid Luna AI button follows its name box, and lacks the class that styles a shown free retry as the primary
 * action (production builds hash class names, so the two buttons' class lists are compared).
 */
async function expectLunaAfterLookup(page: Page) {
  const luna = summaryRegion(page).getByRole('button', { name: 'Use Luna AI (paid)', exact: true }), retry = summaryRegion(page).getByRole('button', { name: 'Retry lookup', exact: true });
  const box = summaryRegion(page).getByRole('group', { name: 'Look up by name', exact: true });
  await expect(box).toBeVisible(); await expect(luna).toBeVisible();
  expect(await box.evaluate((element, button) => Boolean(element.compareDocumentPosition(button as Node) & Node.DOCUMENT_POSITION_FOLLOWING), await luna.elementHandle())).toBe(true);
  if (await retry.count()) {
    const classes = async (button: typeof luna) => (await button.getAttribute('class') ?? '').split(/\s+/).filter(Boolean);
    const lunaClasses = await classes(luna);
    expect((await classes(retry)).filter(name => !lunaClasses.includes(name))).not.toEqual([]);
  }
}
const noOverflow = (page: Page) => page.evaluate(() => document.documentElement.scrollWidth <= innerWidth && document.body.scrollWidth <= innerWidth);

